#!/usr/bin/env python3
"""Reshard a dataset so every directory holds at most 30 entries and every
file is at most 15 MB.

Usage:
    python compress.py <input_dir> <output_dir>

Output layout (reversible with decompress.py):

    <output>/
        __reshard_meta.json    root manifest (JSON, <= 15 MB)
        00000.json, ...        optional extra manifests if the root one
                               would exceed 15 MB
        data/                  tree of chunk files
            0/                 level 1  (at most 30 subdirs per dir)
              0/               level 2
                0/             level 3
                  0/           level 4
                    0          level 5 -> the chunk file itself
                    ...
                    29

Each chunk is at most 15 MB. Every original file is represented as one or
more chunks; identical file contents share one chunk on disk (dedup).
Symlinks are recorded in the manifest and recreated verbatim.
"""

import hashlib
import json
import os
import shutil
import sys

CHUNK_LIMIT = 15 * 1024 * 1024   # max bytes per file
MAX_ENTRIES = 30                 # max direct children per directory
LEVELS = 5                       # depth of the chunk tree
MAX_CHUNKS = MAX_ENTRIES ** LEVELS
MARKER = "__reshard_meta.json"   # root manifest, reserved name
CHUNK_ROOT = "data"              # chunk tree, reserved name
COPY_BUF = 4 * 1024 * 1024


def fail(msg):
    print("compress.py: error: " + msg, file=sys.stderr)
    sys.exit(1)


def rel(path):
    """Relative path with forward slashes (stable JSON key)."""
    return path.replace(os.sep, "/")


def sha1_file(path):
    h = hashlib.sha1()
    with open(path, "rb") as f:
        while True:
            b = f.read(COPY_BUF)
            if not b:
                break
            h.update(b)
    return h.hexdigest()


def sha1_stream(f):
    h = hashlib.sha1()
    while True:
        b = f.read(COPY_BUF)
        if not b:
            break
        h.update(b)
    return h.hexdigest()


def copy_file(src, dst):
    os.makedirs(os.path.dirname(dst), exist_ok=True)
    with open(src, "rb") as fin, open(dst, "wb") as fout:
        while True:
            b = fin.read(COPY_BUF)
            if not b:
                break
            fout.write(b)


def chunk_address(n):
    """Address of the n-th chunk as a LEVELS-deep path of single base-30
    digits. Each directory level holds at most 30 children, so the tree
    can never violate the entry limit."""
    digits = []
    for _ in range(LEVELS):
        digits.append(str(n % MAX_ENTRIES))
        n //= MAX_ENTRIES
    return "/".join(digits)


def json_bytes(obj):
    return len(json.dumps(obj, separators=(",", ":")).encode("utf-8"))


def main():
    if len(sys.argv) != 3:
        print(__doc__.strip(), file=sys.stderr)
        sys.exit(2)
    input_dir = os.path.abspath(sys.argv[1])
    output_dir = os.path.abspath(sys.argv[2])
    if not os.path.isdir(input_dir):
        fail("input directory does not exist: %s" % input_dir)
    if input_dir == output_dir:
        fail("input and output directories must differ")
    if os.path.commonpath([input_dir, output_dir]) in (input_dir, output_dir):
        fail("input and output directories must not be nested")
    if MARKER in os.listdir(input_dir) or CHUNK_ROOT in os.listdir(input_dir):
        fail("input contains reserved name %r or %r; rename and retry"
             % (MARKER, CHUNK_ROOT))

    # ---- Scan the input ----------------------------------------------------
    files = []      # (relpath, size, [chunk hashes])
    symlinks = {}   # relpath -> target
    for dirpath, dirnames, filenames in os.walk(input_dir):
        dirnames.sort()
        for fn in sorted(filenames):
            full = os.path.join(dirpath, fn)
            rp = rel(os.path.relpath(full, input_dir))
            if os.path.islink(full):
                symlinks[rp] = os.readlink(full)
                continue
            size = os.path.getsize(full)
            if size <= CHUNK_LIMIT:
                files.append((rp, size, [sha1_file(full)], full, False))
            else:
                # Split into parts of CHUNK_LIMIT each; record part hashes.
                hashes = []
                with open(full, "rb") as f:
                    while True:
                        b = f.read(CHUNK_LIMIT)
                        if not b:
                            break
                        hashes.append(
                            hashlib.sha1(b).hexdigest()
                            if False else sha1_bytes(b)
                        )
                files.append((rp, size, hashes, full, True))

    # ---- Assign chunk addresses --------------------------------------------
    # Whole files (single part) with identical content share one chunk.
    chunk_addr = {}          # (size, [hashes]) -> address
    chunk_sources = {}       # address -> source spec
    next_chunk = [0]

    def new_addr():
        if next_chunk[0] >= MAX_CHUNKS:
            fail("more than %d unique chunks; not supported" % MAX_CHUNKS)
        a = chunk_address(next_chunk[0])
        next_chunk[0] += 1
        return a

    for rp, size, hashes, full, is_large in files:
        if is_large:
            addr = new_addr()
            chunk_sources[addr] = (full, len(hashes))
        else:
            key = (size, tuple(hashes))
            if key not in chunk_addr:
                addr = new_addr()
                chunk_addr[key] = addr
                chunk_sources[addr] = (full, 1)
        # record entry
        entry = {
            "p": rp,
            "s": size,
            "h": hashes,
            "c": [chunk_addr.get((size, tuple(hashes))) if not is_large
                  else chunk_sources.__iter__.__self__ and None],
        }
        # (fill "c" below once addresses are final)
        entry["c"] = [chunk_addr[(size, tuple(hashes))]] if not is_large else \
                     [a for a in ()]  # placeholder, fixed below
        files_entry = (rp, size, hashes, entry)
        # stash entry on the tuple index
        files[len(files) - 1] = (rp, size, hashes, full, is_large, entry)

    # Build entries with correct addresses.
    entries = []
    for item in files:
        rp, size, hashes, full, is_large, entry = item
        if is_large:
            # large files: one address per part
            # (sources recorded in order; rebuild here deterministically)
            pass
        entries.append(entry)

    # The above got tangled for large files; rebuild entries cleanly.
    entries = []
    large_counter = {}
    for item in files:
        rp, size, hashes, full, is_large, entry = item
        if is_large:
            # addresses were assigned in scan order; recover from sources
            addrs = [a for a in chunk_sources
                     if chunk_sources[a] == (full, len(hashes))]
            entry["c"] = addrs
        entries.append(entry)

    # ---- Write chunk files ---------------------------------------------------
    if os.path.isdir(output_dir) and os.listdir(output_dir):
        fail("output directory must not exist or be empty: %s" % output_dir)
    os.makedirs(output_dir, exist_ok=True)
    data_root = os.path.join(output_dir, CHUNK_ROOT)
    for addr, (src, n_parts) in chunk_sources.items():
        dst_base = os.path.join(data_root, *addr.split("/")[:-1])
        if n_parts == 1:
            copy_file(src, os.path.join(data_root, *addr.split("/")))
        else:
            # source is a big file; copy the i-th part to addr i
            # (part 0's address is addr, part i's address is addr+i+1)
            with open(src, "rb") as f:
                for i in range(n_parts):
                    part_addr = chunk_address(next_chunk_start + i) if False else None
            # (parts are written below in a single streaming pass)
    # Simpler: stream the big files part by part.
    big_written = 0
    for item in files:
        rp, size, hashes, full, is_large, entry = item
        if not is_large:
            continue
        addrs = entry["c"]
        with open(full, "rb") as f:
            for i, a in enumerate(addrs):
                dst = os.path.join(data_root, *a.split("/"))
                os.makedirs(os.path.dirname(dst), exist_ok=True)
                with open(dst, "wb") as out:
                    while True:
                        b = f.read(CHUNK_LIMIT)
                        if not b:
                            break
                        out.write(b)
                big_written += 1

    # ---- Build the root manifest ---------------------------------------------
    # Pack entries into manifest payloads, each <= 15 MB.
    manifest_payloads = []
    group = []
    for e in entries:
        eb = len(e["p"].encode("utf-8")) * 2 + len(json.dumps(
            [e["c"], e["h"]], separators=(",", ":"))) + 30
        if group and (group[-1] + 1) * 0 or True:
            pass
        if group:
            test = list(group)
            test.append(e)
            if json_bytes({"v": 1, "entries": test}) > CHUNK_LIMIT:
                manifest_payloads.append(group)
                group = [e]
            else:
                group = test
        else:
            group = [e]
    if group:
        manifest_payloads.append(group)

    if len(manifest_payloads) == 1:
        meta = {
            "v": 1,
            "chunks_root": CHUNK_ROOT,
            "symlinks": symlinks,
            "entries": manifest_payloads[0],
        }
    else:
        manifest_files = []
        for i, group in enumerate(manifest_payloads):
            name = "%05d.json" % i
            manifest_files.append({"p": name, "n": len(group)})
            with open(os.path.join(output_dir, name), "w",
                      encoding="utf-8") as f:
                json.dump({"v": 1, "entries": group}, f,
                          separators=(",", ":"))
        meta = {
            "v": 1,
            "chunks_root": CHUNK_ROOT,
            "symlinks": symlinks,
            "manifests": manifest_files,
        }

    # Keep the marker itself under the limit: if the symlinks map is huge,
    # spill it into separate files.
    if json_bytes(meta) > CHUNK_LIMIT:
        link_groups = []
        items = list(symlinks.items())
        group = {}
        for k, v in items:
            trial = dict(group)
            trial[k] = v
            if group and json_bytes({"symlinks": trial}) > CHUNK_LIMIT:
                link_groups.append(group)
                group = {k: v}
            else:
                group = trial
        if group:
            link_groups.append(group)
        link_files = []
        for i, g in enumerate(link_groups):
            name = "links-%04d.json" % i
            link_files.append({"p": name})
            with open(os.path.join(output_dir, name), "w",
                      encoding="utf-8") as f:
                json.dump({"symlinks": g}, f, separators=(",", ":"))
        meta = {
            "v": 1,
            "chunks_root": CHUNK_ROOT,
            "links": link_files,
            "entries": meta.get("entries"),
            "manifests": meta.get("manifests"),
        }
        meta = {k: v for k, v in meta.items() if v is not None}

    with open(os.path.join(output_dir, MARKER), "w", encoding="utf-8") as f:
        json.dump(meta, f, separators=(",", ":"))

    total_bytes = sum(e["s"] for e in entries)
    print("compress: %d files, %d bytes, %d unique chunks, %d symlinks"
          % (len(entries), total_bytes, len(chunk_sources), len(symlinks)))


def sha1_bytes(b):
    return hashlib.sha1(b).hexdigest()


if __name__ == "__main__":
    main()

